"""Independent complete-boundary screen of measured ordinary effusion apparatus.
Not a reinterpretation of missing current waveform as a measured wall-plug bill.
"""
from pathlib import Path
import json,time,resource
import numpy as np
D=Path(__file__).resolve().parent;start=time.monotonic()
raw={'nozzle':{'P_W':[155.85,158.41,162.48],'NO_percent':[2.25,2.26,2.27],'NO2_percent':[1.64,1.64,1.60]},'without_nozzle':{'P_W':[193.43,205.59,196.73],'NO_percent':[2.28,2.29,2.28],'NO2_percent':[1.46,1.49,1.48]}}
F=2/24/60;R=25000.;I=.135;ballast=R*I*I;out={}
for key,a in raw.items():
 p=np.array(a['P_W']);no=np.array(a['NO_percent'])/100;no2=np.array(a['NO2_percent'])/100
 # Paper's feed-volumetric production approximation and four-species molar contraction.
 rate_paper=F*(no+no2);rate_balanced=rate_paper/(1+.5*no2)
 out[key]={'raw':a,'flow_L_min':2,'inlet_molar_volume_L_mol_as_paper':24,'reported_applied_current_A':I,'mean_discharge_power_W':float(p.mean()),'mean_NOx_percent':float(100*(no+no2).mean()),'mean_production_paper_mol_s':float(rate_paper.mean()),'mean_production_four_species_balanced_mol_s':float(rate_balanced.mean()),'ratio_of_means_discharge_SEC_paper_MJ_mol':float(p.mean()/rate_paper.mean()/1e6),'ratio_of_means_discharge_SEC_balanced_MJ_mol':float(p.mean()/rate_balanced.mean()/1e6),'conditional_discharge_plus_ballast_floor_SEC_MJ_mol':float((p.mean()+ballast)/rate_balanced.mean()/1e6),'replicate_discharge_SEC_balanced_MJ_mol':(p/rate_balanced/1e6).tolist(),'sample_sd_discharge_power_W':float(p.std(ddof=1)),'sample_sd_NOx_percent':float(100*(no+no2).std(ddof=1)),'minimum_current_rms_A_for_ballast_exceeding_discharge_mean':float(np.sqrt(p.mean()/R))}
a=out['nozzle'];b=out['without_nozzle'];f=a['mean_production_four_species_balanced_mol_s']/b['mean_production_four_species_balanced_mol_s'];pa=a['mean_discharge_power_W'];pb=b['mean_discharge_power_W']
result={'scope':__doc__,'primary_source':'Van Alphen et al., Chemical Engineering Journal443(2022)136529, doi10.1016/j.cej.2022.136529. Main section2 and SI tablesS2,S4. Three80/20 N2/O2 steady rows,2L/min,135mA. Main reference293.15K,1atm,24L/mol. This is NOT the owner79/21,300K,2700K ideal-heater contract.','cases':out,'ballast_ohm':R,'conditional_ballast_power_W':ballast,'conditional_ballast_statement':'If reported135mA is the time-mean current through the series25kOhm resistor, mean RI^2>=R mean(I)^2=455.625W. If it is RMS, equality. If it is merely a setting/peak, no such numeric lower bound follows without waveform. Source describes applied current but does not explicitly define this table statistic.','measured_discharge_only_ratio_of_means_improvement_fraction':1-a['ratio_of_means_discharge_SEC_balanced_MJ_mol']/b['ratio_of_means_discharge_SEC_balanced_MJ_mol'],'hypothetical_same_constant_135mA_ballast_ratio_of_means_improvement_fraction':1-(pa+ballast)/(pb+ballast)/f,'as_common_ballast_dominates_limit_improvement_fraction':1-1/f,'same_current_common_loss_counterfactual_formula':'improvement=1-(Pa+B)/(Pb+B)*(rate_b/rate_a), only when the same B is actually common. Separate current-variance losses need not be identical. Individual lower bounds cannot determine true total-energy ranking.','ballast_replacement_counterfactual':{'description':'An ordinary efficient current regulator at the same measured discharge state would avoid most ballast waste, if it preserved that state. No circuit built and no identical-state control demonstrated. Break-even additional regulator loss below455.625W versus constant135mA ballast, before supply-efficiency differences.','nozzle_constant_current_fraction_of_discharge_plus_ballast_in_ballast':ballast/(pa+ballast)},'molar_contraction_scope':'For dryN2/O2 feed and onlyN2,O2,NO,NO2 outlet with no wall inventory/other species and relaxed measured gas, Fout=Fin/(1+xNO2/2). Derived by summing atom balances. Extra species/wall erosion/sorption or unmeasured outlet flow invalidate exact use; correction here is a conditional bookkeeping sensitivity, not a newly measured rate.','uncertainty':['Only3 published runs; ranges/sample SD are not independent-culture-style precision or a systematic calibration confidence interval. No raw voltage/current waveform, meter error or power-supply input exists in supplied source.','NO+NO2 measured downstream can survive NO/NO2 interconversion, but N2O/NO3/N2O5, wall deposits/erosion and sample handling remain unclosed at full-process precision.','Divider partially melted. Stable downstream NOx over65min does not establish material/inventory reset or long-life operation.','Plasma powers and arc attachment differ between devices. Observed energy-per-mole change is not a matched-power isolated quench effect.','Gas supply/compression, MFC, analyzer sample pump, power electronics, cooling fan if added, startup, capture and fertilizer processing are not in discharge SEC. No wall-plug or plant result claimed.'],'elapsed_s':time.monotonic()-start,'RSS_KiB':resource.getrusage(resource.RUSAGE_SELF).ru_maxrss}
(D/'result.json').write_text(json.dumps(result,indent=2));(D/'input_rows.json').write_text(json.dumps(raw,indent=2));print(json.dumps(result,indent=2))
